import { cn } from "@/lib/utils";
import Mapbox from "@rnmapbox/maps";
import * as Location from "expo-location";
import React, {
  createContext,
  use,
  useCallback,
  useEffect,
  useImperativeHandle,
  useMemo,
  useRef,
  useState,
  type ReactNode,
  type Ref,
} from "react";
import { ActivityIndicator, useColorScheme, View } from "react-native";
import {
  CAPABILITIES,
  createCameraController,
  MapboxMapView,
  normalizeRegionChangeEvent,
  RENDERER,
  type MapboxCameraRef,
  type MapboxMapViewRef,
} from "./map-renderer";
import type { MapInstance, MapProps } from "./map-types";
import { PROVIDERS, resolveStyleUrl } from "@/lib/mapcn/provider";
import { viewportEquals } from "@/lib/mapcn/geo";
import type { MapViewport, PartialViewport } from "@/lib/mapcn/types";

export type { MapProps };
export { CAPABILITIES as MAP_CAPABILITIES };

const MapContext = createContext<MapInstance | null>(null);

function useMap(): MapInstance {
  const context = use(MapContext);
  if (!context) {
    throw new Error("useMap must be used within a Map component");
  }
  return context;
}

/**
 * Mapbox's MapView can't render arbitrary RN children as overlays the way
 * MapLibre's Map can (plan §14 risk #3) -- `MapControls` and friends
 * register their rendered element here instead, and `Map` renders the
 * registry as siblings of MapView. This is intentionally a separate,
 * non-public context: `useMap()` only ever exposes the shared `MapInstance`
 * shape, never this renderer-specific plumbing.
 */
const OverlayContext = createContext<{
  registerOverlay: (id: string, element: ReactNode) => void;
  unregisterOverlay: (id: string) => void;
} | null>(null);

function useOverlay() {
  const context = use(OverlayContext);
  if (!context) {
    throw new Error("useOverlay must be used within a Map component");
  }
  return context;
}

const DEFAULT_VIEWPORT: MapViewport = { center: [0, 0], zoom: 10, bearing: 0, pitch: 0 };
const DEFAULT_VIEWPORT_CHANGE_THROTTLE = 100;

function isLightDarkPair(
  style: NonNullable<MapProps["style"]>,
): style is { light: string | Record<string, unknown>; dark: string | Record<string, unknown> } {
  return typeof style === "object" && ("light" in style || "dark" in style);
}

function resolveMapStyle(
  style: MapProps["style"],
  colorScheme: "light" | "dark",
  provider: (typeof PROVIDERS)[keyof typeof PROVIDERS],
): string | Record<string, unknown> {
  const resolved: string | Record<string, unknown> | undefined = style
    ? isLightDarkPair(style)
      ? style[colorScheme]
      : style
    : undefined;

  if (resolved === undefined) {
    const defaultStyleId = provider.defaultStyle[colorScheme];
    return resolveStyleUrl(provider, defaultStyleId, process.env.EXPO_PUBLIC_MAPBOX_TOKEN);
  }
  if (typeof resolved === "string" && !resolved.includes("://") && !resolved.startsWith("http")) {
    return resolveStyleUrl(provider, resolved, process.env.EXPO_PUBLIC_MAPBOX_TOKEN);
  }
  return resolved;
}

const DefaultLoader = () => (
  <View className="absolute inset-0 justify-center items-center bg-background/80">
    <ActivityIndicator size="small" color="#999" />
  </View>
);

let accessTokenSet = false;

function ensureAccessToken() {
  if (accessTokenSet) return;
  accessTokenSet = true;
  const token = process.env.EXPO_PUBLIC_MAPBOX_TOKEN;
  if (token) {
    Mapbox.setAccessToken(token);
  } else {
    console.warn(
      "[mapcn] EXPO_PUBLIC_MAPBOX_TOKEN not found. Get a free token at https://account.mapbox.com/access-tokens/",
    );
  }
}

function Map({
  children,
  style,
  provider: providerId = "mapbox",
  colorScheme: colorSchemeProp,
  viewport,
  defaultViewport,
  onViewportChange,
  onViewportChangeEnd,
  viewportChangeThrottle = DEFAULT_VIEWPORT_CHANGE_THROTTLE,
  bounds,
  padding,
  minZoom,
  maxZoom,
  maxBounds,
  interactive = true,
  gestures,
  compass = false,
  logo = false,
  attribution = false,
  scaleBar = false,
  onPress,
  onLongPress,
  onLoad,
  onError: _onError,
  className,
  containerStyle,
  loader,
  ref,
}: MapProps & { ref?: Ref<MapInstance> }) {
  ensureAccessToken();

  const mapRef = useRef<MapboxMapViewRef | null>(null);
  const cameraRef = useRef<MapboxCameraRef | null>(null);
  const [isLoaded, setIsLoaded] = useState(false);
  const [overlays, setOverlays] = useState<Record<string, ReactNode>>({});

  const systemColorScheme = useColorScheme();
  const colorScheme: "light" | "dark" = colorSchemeProp ?? (systemColorScheme === "dark" ? "dark" : "light");
  const provider = PROVIDERS[providerId];

  const isControlled = viewport !== undefined;
  const initialViewport: MapViewport = { ...DEFAULT_VIEWPORT, ...defaultViewport, ...viewport };

  const lastEmittedRef = useRef<MapViewport>(initialViewport);
  const lastAppliedRef = useRef<MapViewport>(initialViewport);
  const isGestureActiveRef = useRef(false);

  const mapStyle = resolveMapStyle(style, colorScheme, provider);

  const registerOverlay = useCallback((id: string, element: ReactNode) => {
    setOverlays((prev) => ({ ...prev, [id]: element }));
  }, []);

  const unregisterOverlay = useCallback((id: string) => {
    setOverlays((prev) => {
      const next = { ...prev };
      delete next[id];
      return next;
    });
  }, []);

  const overlayContextValue = useMemo(() => ({ registerOverlay, unregisterOverlay }), [registerOverlay, unregisterOverlay]);

  // createCameraController only stores these ref objects; every `.current`
  // read happens inside the closures it returns, which only ever run from
  // event handlers/effects (see map-renderer.tsx) -- never during render.
  // eslint-disable-next-line react-hooks/refs
  const cameraController = useMemo(() => createCameraController(mapRef, cameraRef), []);

  const instance = useMemo<MapInstance>(
    () => ({
      renderer: RENDERER,
      isLoaded,
      mapRef,
      cameraRef,
      ...cameraController,
    }),
    [isLoaded, cameraController],
  );

  useImperativeHandle(ref, () => instance, [instance]);

  const throttleTimer = useRef<ReturnType<typeof setTimeout> | null>(null);
  const pendingViewport = useRef<{ viewport: MapViewport; userInteraction: boolean } | null>(null);

  const flushViewportChange = useCallback(() => {
    if (!pendingViewport.current) return;
    const { viewport: next, userInteraction } = pendingViewport.current;
    pendingViewport.current = null;
    lastEmittedRef.current = next;
    onViewportChange?.(next, { userInteraction });
  }, [onViewportChange]);

  const handleCameraChanged = useCallback(
    (event: Parameters<typeof normalizeRegionChangeEvent>[0]) => {
      const { viewport: next, userInteraction } = normalizeRegionChangeEvent(event as never);
      isGestureActiveRef.current = userInteraction;
      if (viewportEquals(next, lastAppliedRef.current) || viewportEquals(next, lastEmittedRef.current)) return;

      pendingViewport.current = { viewport: next, userInteraction };
      if (throttleTimer.current) return;
      throttleTimer.current = setTimeout(() => {
        throttleTimer.current = null;
        flushViewportChange();
      }, viewportChangeThrottle);
    },
    [flushViewportChange, viewportChangeThrottle],
  );

  const handleMapIdleRegion = useCallback(
    (event: Parameters<typeof normalizeRegionChangeEvent>[0]) => {
      const { viewport: next, userInteraction } = normalizeRegionChangeEvent(event as never);
      isGestureActiveRef.current = false;
      if (throttleTimer.current) {
        clearTimeout(throttleTimer.current);
        throttleTimer.current = null;
      }
      pendingViewport.current = null;
      if (!viewportEquals(next, lastEmittedRef.current)) {
        lastEmittedRef.current = next;
        onViewportChange?.(next, { userInteraction });
      }
      onViewportChangeEnd?.(next, { userInteraction });
    },
    [onViewportChange, onViewportChangeEnd],
  );

  useEffect(() => {
    if (!isControlled || !isLoaded || isGestureActiveRef.current) return;
    if (viewportEquals(lastEmittedRef.current, viewport as PartialViewport)) return;
    lastAppliedRef.current = { ...lastAppliedRef.current, ...viewport };
    cameraController.setViewport(viewport as PartialViewport, { duration: 300, easing: "ease" });
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [viewport, isControlled, isLoaded]);

  const handleDidFinishLoadingMap = useCallback(() => {
    setIsLoaded(true);
    onLoad?.();
  }, [onLoad]);

  return (
    <MapContext value={instance}>
      <OverlayContext value={overlayContextValue}>
        <View className={cn("flex-1 relative", className)} style={containerStyle}>
          <MapboxMapView
            ref={mapRef}
            style={{ flex: 1 }}
            styleURL={typeof mapStyle === "string" ? mapStyle : undefined}
            styleJSON={typeof mapStyle === "object" ? JSON.stringify(mapStyle) : undefined}
            onDidFinishLoadingMap={handleDidFinishLoadingMap}
            onCameraChanged={handleCameraChanged}
            onMapIdle={handleMapIdleRegion}
            onPress={onPress ? ((feature: unknown) => onPress(normalizePress(feature))) : undefined}
            onLongPress={onLongPress ? ((feature: unknown) => onLongPress(normalizePress(feature))) : undefined}
            compassEnabled={compass !== false}
            logoEnabled={logo !== false}
            attributionEnabled={attribution !== false}
            scaleBarEnabled={scaleBar !== false}
            scrollEnabled={interactive && gestures?.pan !== false}
            zoomEnabled={interactive && gestures?.zoom !== false}
            rotateEnabled={interactive && gestures?.rotate !== false}
            pitchEnabled={interactive && gestures?.pitch !== false}
            contentInset={padding ? [padding.top ?? 0, padding.right ?? 0, padding.bottom ?? 0, padding.left ?? 0] : undefined}
          >
            <Mapbox.Camera
              ref={cameraRef}
              defaultSettings={{
                centerCoordinate: initialViewport.center,
                zoomLevel: initialViewport.zoom,
                heading: initialViewport.bearing,
                pitch: initialViewport.pitch,
                ...(bounds
                  ? { bounds: { ne: [bounds[2], bounds[3]], sw: [bounds[0], bounds[1]] } }
                  : {}),
              }}
              minZoomLevel={minZoom}
              maxZoomLevel={maxZoom}
              maxBounds={maxBounds ? { ne: [maxBounds[2], maxBounds[3]], sw: [maxBounds[0], maxBounds[1]] } : undefined}
            />
            {children}
          </MapboxMapView>
          {loader !== false && !isLoaded && (loader ?? <DefaultLoader />)}
          {Object.entries(overlays).map(([id, element]) => (
            <React.Fragment key={id}>{element}</React.Fragment>
          ))}
        </View>
      </OverlayContext>
    </MapContext>
  );
}

Map.displayName = "Map";


function normalizePress(feature: any) {
  return {
    coordinate: feature.geometry.coordinates as [number, number],
    point: { x: 0, y: 0 },
    features: [feature],
  };
}

type MapUserLocationProps = {
  /** Show user location on the map */
  visible?: boolean;
  /** Show accuracy circle around user location */
  showAccuracy?: boolean;
  /** Show heading arrow indicating device direction */
  showHeading?: boolean;
  /** Whether the location marker is animated between updates */
  animated?: boolean;
  /** Minimum delta in meters for location updates */
  minDisplacement?: number;
  /** Callback when user location is pressed */
  onPress?: () => void;
  /** Auto-request location permissions if not granted */
  autoRequestPermission?: boolean;
};

function MapUserLocation({
  visible = true,
  showAccuracy = true,
  showHeading = false,
  animated = true,
  minDisplacement,
  onPress,
  autoRequestPermission = true,
}: MapUserLocationProps) {
  const [hasPermission, setHasPermission] = useState(false);
  const [permissionChecked, setPermissionChecked] = useState(false);

  useEffect(() => {
    let mounted = true;

    const checkAndRequestPermissions = async () => {
      try {
        if (autoRequestPermission) {
          const { status } = await Location.requestForegroundPermissionsAsync();
          if (mounted) {
            setHasPermission(status === "granted");
            setPermissionChecked(true);
          }
        } else {
          if (mounted) {
            setPermissionChecked(true);
          }
        }
      } catch (error) {
        console.error("Error requesting location permissions:", error);
        if (mounted) {
          setHasPermission(false);
          setPermissionChecked(true);
        }
      }
    };

    if (visible) {
      checkAndRequestPermissions();
    }

    return () => {
      mounted = false;
    };
  }, [visible, autoRequestPermission]);

  if (!visible || !permissionChecked || !hasPermission) {
    return null;
  }

  return (
    <Mapbox.LocationPuck
      puckBearingEnabled={showHeading}
      pulsing={{ isEnabled: animated }}
    />
  );
}

export { Map, MapUserLocation, useMap, useOverlay };

/**
 * The Mapbox implementation of the renderer adapter boundary (plan §2 D2).
 * See apps/demo-maplibre/src/components/ui/map-renderer.tsx for the sibling
 * implementation and the rationale for what does/doesn't live here.
 */
import type { ComponentType, ReactElement, ReactNode, Ref } from "react";
import { useImperativeHandle, useRef } from "react";
import type { Feature } from "geojson";
import type { NativeSyntheticEvent } from "react-native";
import Mapbox, {
  type Camera as MapboxCameraRef,
  type MapView as MapboxMapViewRef,
} from "@rnmapbox/maps";
import type {
  Bounds,
  Coordinate,
  Expression,
  GeoJSONInput,
  MapCameraAnimation,
  MapFeaturePressEvent,
  MapRenderer,
  MapViewport,
  ScreenPoint,
} from "@/lib/mapcn/types";
import type { MapInstanceMethods, RendererCapabilities } from "@/components/ui/map-types";
import { bboxOf } from "@/lib/mapcn/geo";

export { Mapbox };
export type { MapboxCameraRef, MapboxMapViewRef };

/**
 * @rnmapbox/maps@10.3.5's class components that extend the internal
 * `NativeBridgeComponent` mixin (MapView, Callout, ShapeSource, and every
 * *Layer) are not structurally assignable to React 19.2's `Component` type
 * under TS 6 (confirmed during Phase 0: MarkerView and Camera, which don't
 * use that mixin, typecheck fine as JSX). This is an upstream typing gap,
 * not a bug in this codebase -- every file that needs to render one of
 * these imports the pre-cast version from here instead of re-deriving the
 * same `as unknown as ComponentType<any>` workaround at each call site.
 */
export const MapboxMapView = Mapbox.MapView as unknown as ComponentType<any>;
export const MapboxCallout = Mapbox.Callout as unknown as ComponentType<any>;
export const MapboxShapeSource = Mapbox.ShapeSource as unknown as ComponentType<any>;
export const MapboxLineLayer = Mapbox.LineLayer as unknown as ComponentType<any>;
export const MapboxFillLayer = Mapbox.FillLayer as unknown as ComponentType<any>;
export const MapboxCircleLayer = Mapbox.CircleLayer as unknown as ComponentType<any>;
export const MapboxSymbolLayer = Mapbox.SymbolLayer as unknown as ComponentType<any>;

/**
 * Anchors arbitrary RN content at a geographic coordinate using the
 * renderer's native marker mechanism -- correctness (never drifts during
 * pan/zoom) over a manually re-projected overlay, which is why `MapPopup`
 * (plan §7.10) is built on this instead of `useMap().project()` polling.
 */
export function MapMarkerAnchor({
  id,
  coordinate,
  children,
}: {
  id: string;
  coordinate: Coordinate;
  children: ReactElement;
}) {
  return (
    <Mapbox.MarkerView id={id} coordinate={coordinate} anchor={{ x: 0.5, y: 1 }}>
      {children}
    </Mapbox.MarkerView>
  );
}

export interface MapSourceProps {
  id: string;
  data: GeoJSONInput;
  children?: ReactNode;
  cluster?: boolean;
  clusterRadius?: number;
  clusterMaxZoom?: number;
  /** MapLibre only -- see CAPABILITIES.clusterMinPoints. Silently ignored here, not passed to ShapeSource. */
  clusterMinPoints?: number;
  clusterProperties?: Record<string, unknown>;
  onPress?: (event: NativeSyntheticEvent<unknown>) => void;
  hitbox?: { width: number; height: number };
}

/** Normalized cluster-query surface -- see MapClusterLayer, which is the only consumer of this ref. */
export interface MapSourceRef {
  getClusterExpansionZoom(cluster: Feature): Promise<number>;
  getClusterLeaves(cluster: Feature, limit: number, offset: number): Promise<Array<Feature>>;
}

/** A GeoJSON data source, normalized across renderers -- the foundation MapRoute/MapGeoJSON/MapClusterLayer build on. */
export function MapSource({
  id,
  data,
  children,
  cluster,
  clusterRadius,
  clusterMaxZoom,
  clusterProperties,
  onPress,
  hitbox,
  ref,
}: MapSourceProps & { ref?: Ref<MapSourceRef> }) {

  const internalRef = useRef<any>(null);

  useImperativeHandle(
    ref,
    () => ({
      async getClusterExpansionZoom(clusterFeature) {
        return (await internalRef.current?.getClusterExpansionZoom(clusterFeature)) ?? 0;
      },
      async getClusterLeaves(clusterFeature, limit, offset) {
        return (await internalRef.current?.getClusterLeaves(clusterFeature, limit, offset)) ?? [];
      },
    }),
    [],
  );

  return (
    <MapboxShapeSource
      ref={internalRef}
      id={id}
      shape={data}
      cluster={cluster}
      clusterRadius={clusterRadius}
      clusterMaxZoomLevel={clusterMaxZoom}
      clusterProperties={clusterProperties}
      onPress={onPress}
      hitbox={hitbox}
    >
      {children}
    </MapboxShapeSource>
  );
}

export type MapLayerType = "fill" | "line" | "circle" | "symbol" | "heatmap";

export interface MapLayerProps {
  id: string;
  type: MapLayerType;
  style?: Record<string, unknown>;
  filter?: Expression;
  beforeId?: string;
  minZoom?: number;
  maxZoom?: number;
}

const LAYER_BY_TYPE: Record<MapLayerType, ComponentType<any>> = {
  fill: MapboxFillLayer,
  line: MapboxLineLayer,
  circle: MapboxCircleLayer,
  symbol: MapboxSymbolLayer,
  heatmap: Mapbox.HeatmapLayer as unknown as ComponentType<any>,
};

export function MapLayer({ id, type, style, filter, beforeId, minZoom, maxZoom }: MapLayerProps) {
  const LayerComponent = LAYER_BY_TYPE[type];
  return <LayerComponent id={id} style={style} filter={filter} aboveLayerID={beforeId} minZoomLevel={minZoom} maxZoomLevel={maxZoom} />;
}

export const RENDERER: MapRenderer = "mapbox";

export const CAPABILITIES: RendererCapabilities = {
  clusterMinPoints: false,
  locationPuckPulsing: true,
  locationPuckScale: true,
  locationPuckImages: true,
  locationPuckPress: false,
  locationPuckCustomChildren: false,
};

interface RegionPayload {
  zoomLevel: number;
  heading: number;
  pitch: number;
  visibleBounds: Array<Array<number>>;
  isUserInteraction: boolean;
}

/**
 * MapView's region-change callbacks hand back a GeoJSON Feature<Point,
 * RegionPayload> rather than a plain object (see plan §1.2 upstream
 * research) -- this pulls the fields `Map`/`useMap` actually need out of it.
 */
export function normalizeRegionChangeEvent(feature: {
  geometry: { coordinates: Coordinate };
  properties: RegionPayload;
}): { viewport: MapViewport; userInteraction: boolean } {
  const { coordinates } = feature.geometry;
  const { zoomLevel, heading, pitch, isUserInteraction } = feature.properties;
  return {
    viewport: { center: coordinates, zoom: zoomLevel, bearing: heading, pitch },
    userInteraction: isUserInteraction,
  };
}

export function normalizeFeaturePress(feature: {
  geometry: { coordinates: Coordinate };
  properties?: { screenPointX?: number; screenPointY?: number };

  features?: Array<any>;
}): MapFeaturePressEvent {
  return {
    coordinate: feature.geometry.coordinates,
    point: { x: feature.properties?.screenPointX ?? 0, y: feature.properties?.screenPointY ?? 0 },
    features: feature.features ?? [],
  };
}

function toMapboxPadding(padding: MapCameraAnimation["padding"]) {
  if (!padding) return undefined;
  return {
    paddingTop: padding.top ?? 0,
    paddingRight: padding.right ?? 0,
    paddingBottom: padding.bottom ?? 0,
    paddingLeft: padding.left ?? 0,
  };
}

function toAnimationMode(easing: MapCameraAnimation["easing"]): "flyTo" | "easeTo" | "linearTo" {
  if (easing === "linear") return "linearTo";
  if (easing === "fly") return "flyTo";
  return "easeTo";
}

/**
 * Builds the camera-facing subset of `MapInstance` on top of Mapbox's
 * native `MapView`/`Camera` refs. `map.tsx` combines this with `isLoaded`,
 * `renderer` and the raw refs to produce the full instance handed out by
 * `useMap()`.
 */
export function createCameraController(
  mapRef: { current: MapboxMapViewRef | null },
  cameraRef: { current: MapboxCameraRef | null },
): MapInstanceMethods {
  return {
    async getViewport() {
      const [center, zoom] = await Promise.all([mapRef.current?.getCenter(), mapRef.current?.getZoom()]);
      if (!center || zoom === undefined) {
        throw new Error("[mapcn] getViewport() called before the map finished loading");
      }
      // Mapbox's MapView doesn't expose heading/pitch directly; Camera's
      // onCameraChanged (wired in map.tsx) is the source of truth for those
      // while the map is live. At rest we report 0 rather than stale state.
      return { center: center as Coordinate, zoom, bearing: 0, pitch: 0 };
    },

    setViewport(viewport, animation) {
      cameraRef.current?.setCamera({
        centerCoordinate: viewport.center,
        zoomLevel: viewport.zoom,
        heading: viewport.bearing,
        pitch: viewport.pitch,
        padding: toMapboxPadding(animation?.padding),
        animationDuration: animation?.duration ?? 0,
        animationMode: toAnimationMode(animation?.easing),
      });
    },

    flyTo(center, options) {
      cameraRef.current?.setCamera({
        centerCoordinate: center,
        zoomLevel: options?.zoom,
        padding: toMapboxPadding(options?.padding),
        animationDuration: options?.duration ?? 1000,
        animationMode: "flyTo",
      });
    },

    moveTo(center, options) {
      cameraRef.current?.setCamera({
        centerCoordinate: center,
        zoomLevel: options?.zoom,
        padding: toMapboxPadding(options?.padding),
        animationDuration: options?.duration ?? 0,
        animationMode: (options?.duration ?? 0) > 0 ? toAnimationMode(options?.easing) : "linearTo",
      });
    },

    zoomTo(zoom, options) {
      cameraRef.current?.setCamera({
        zoomLevel: zoom,
        animationDuration: options?.duration ?? 0,
        animationMode: toAnimationMode(options?.easing),
      });
    },

    async zoomBy(delta, options) {
      const currentZoom = (await mapRef.current?.getZoom()) ?? 0;
      cameraRef.current?.setCamera({
        zoomLevel: currentZoom + delta,
        animationDuration: options?.duration ?? 0,
        animationMode: toAnimationMode(options?.easing),
      });
    },

    fitBounds(bounds, options) {
      const [west, south, east, north] = bounds as Bounds;
      cameraRef.current?.setCamera({
        bounds: {
          ne: [east, north],
          sw: [west, south],
          ...toMapboxPadding(options?.padding),
        },
        animationDuration: options?.duration ?? 0,
        animationMode: toAnimationMode(options?.easing),
      });
    },

    fitFeatures(data, options) {
      const [west, south, east, north] = bboxOf(data);
      cameraRef.current?.setCamera({
        bounds: {
          ne: [east, north],
          sw: [west, south],
          ...toMapboxPadding(options?.padding),
        },
        animationDuration: options?.duration ?? 0,
        animationMode: toAnimationMode(options?.easing),
      });
    },

    resetNorth(options) {
      cameraRef.current?.setCamera({
        heading: 0,
        animationDuration: options?.duration ?? 300,
        animationMode: toAnimationMode(options?.easing),
      });
    },

    async project(coordinate) {
      const point = await mapRef.current?.getPointInView(coordinate);
      if (!point) throw new Error("[mapcn] project() called before the map finished loading");
      return { x: point[0] as number, y: point[1] as number };
    },

    async unproject(point) {
      const coordinate = await mapRef.current?.getCoordinateFromView([point.x, point.y]);
      if (!coordinate) throw new Error("[mapcn] unproject() called before the map finished loading");
      return coordinate as Coordinate;
    },

    async queryFeatures(options) {
      // See MapLibre adapter for why `filter` is cast at this boundary: the
      // shared `Expression` type is intentionally loose to match both
      // renderers' style-spec grammar.
      const filter = options?.filter as never;

      if (options?.point) {
        const result = await mapRef.current?.queryRenderedFeaturesAtPoint(
          [options.point.x, options.point.y],
          filter,
          options.layers,
        );
        return result?.features ?? [];
      }

      if (options?.bounds) {
        const rect = await geographicBoundsToPixelRect(mapRef.current, options.bounds);
        if (!rect) return [];
        const result = await mapRef.current?.queryRenderedFeaturesInRect(rect, filter, options.layers);
        return result?.features ?? [];
      }

      // rnmapbox has no "query the whole current viewport" call that
      // doesn't need an explicit pixel rect (unlike MapLibre's
      // `queryRenderedFeatures()` with no arguments) -- documented gap, not
      // silently faked. Callers needing this should query against
      // `mapRef.current` directly with the screen's own dimensions.
      return [];
    },
  };
}

async function geographicBoundsToPixelRect(
  map: MapboxMapViewRef | null | undefined,
  bounds: Bounds,
): Promise<[number, number, number, number] | null> {
  if (!map) return null;
  const [west, south, east, north] = bounds;
  const topLeft = (await map.getPointInView([west, north])) as [number, number] | undefined;
  const bottomRight = (await map.getPointInView([east, south])) as [number, number] | undefined;
  if (!topLeft || !bottomRight) return null;
  // queryRenderedFeaturesInRect expects [top, left, bottom, right] (see the
  // upstream doc comment on MapView.queryRenderedFeaturesInRect).
  return [topLeft[1], topLeft[0], bottomRight[1], bottomRight[0]];
}

export function screenPointOf(x: number, y: number): ScreenPoint {
  return { x, y };
}
